<script>
const webinarTabKey='webinar-tab-{{ $webinar->id }}';
window.activateWebinarTab=key=>{let tab=document.querySelector(`[data-module-tab="${key}"]`);if(!tab||tab.hidden||tab.dataset.moduleEnabled==='false'){tab=document.querySelector('[data-module-tab][data-module-enabled="true"]:not([hidden])');}if(!tab)return;const activeKey=tab.dataset.moduleTab;document.querySelectorAll('[data-module-tab]').forEach(item=>item.classList.toggle('active',item===tab));document.querySelectorAll('[data-module-panel]').forEach(panel=>panel.classList.toggle('active',panel.dataset.modulePanel===activeKey));sessionStorage.setItem(webinarTabKey,activeKey)};
window.setDashboardModuleState=(key,enabled)=>{const tab=document.querySelector(`[data-module-tab="${key}"]`);const panel=document.querySelector(`[data-module-panel="${key}"]`);if(tab){tab.hidden=!enabled;tab.style.display=enabled?'':'none';tab.dataset.moduleEnabled=enabled?'true':'false';}if(panel){panel.hidden=!enabled;panel.style.display=enabled?'':'none';panel.dataset.moduleEnabled=enabled?'true':'false';}if(!enabled&&tab?.classList.contains('active')){const nextTab=document.querySelector('[data-module-tab][data-module-enabled="true"]:not([hidden])');if(nextTab)window.activateWebinarTab(nextTab.dataset.moduleTab);}};
window.refreshActivePoll=async()=>{const container=document.querySelector('[data-poll-container]');if(!container||!container.dataset.pollUrl)return;try{const response=await fetch(container.dataset.pollUrl,{headers:{'Accept':'text/html','X-Requested-With':'XMLHttpRequest'},cache:'no-store'});if(response.ok){container.innerHTML=await response.text();window.bindInstantPoll?.(container);}}catch(e){console.warn('Unable to refresh poll',e);}};
document.querySelectorAll('[data-module-tab]').forEach(tab=>tab.addEventListener('click',()=>{window.activateWebinarTab(tab.dataset.moduleTab)}));
window.activateWebinarTab(sessionStorage.getItem(webinarTabKey)||document.querySelector('[data-module-tab].active')?.dataset.moduleTab);
if(location.hash)history.replaceState(null,'',location.pathname+location.search);
const showDashboardToast=(message,tone='success')=>{
    if (typeof window.showToast === 'function') {
        window.showToast(message, tone);
        return;
    }
    let container = document.getElementById('simpleToastContainer');
    if (!container) {
        container = document.createElement('div');
        container.id = 'simpleToastContainer';
        container.className = 'simple-toast-container';
        document.body.appendChild(container);
    }
    const toast = document.createElement('div');
    toast.className = `simple-toast simple-toast-${tone}`;
    let icon = 'bi-check-circle-fill';
    if (tone === 'warning') icon = 'bi-exclamation-circle-fill';
    else if (tone === 'danger' || tone === 'error') icon = 'bi-x-circle-fill';
    else if (tone === 'info') icon = 'bi-info-circle-fill';
    toast.innerHTML = `<i class="bi ${icon}"></i><span class="simple-toast-msg">${message}</span><button type="button" class="simple-toast-close" aria-label="Close">&times;</button>`;
    container.appendChild(toast);
    const dismiss = () => { toast.classList.add('simple-toast-leaving'); setTimeout(() => toast.remove(), 250); };
    toast.querySelector('.simple-toast-close')?.addEventListener('click', dismiss);
    setTimeout(dismiss, 3200);
    const testToast = document.querySelector('#appToast');
    if (testToast) {
        const span = testToast.querySelector('span');
        if (span) span.textContent = message;
    }
};
@include('pages.user.partials.poll-script')
const renderAgendaNow=()=>{const now=Date.now();document.querySelectorAll('[data-agenda-start]').forEach(item=>{const start=new Date(item.dataset.agendaStart).getTime(),end=start+(Number(item.dataset.agendaDuration)||30)*60000;item.classList.toggle('is-current',now>=start&&now<end)})};renderAgendaNow();setInterval(renderAgendaNow,30000);
document.querySelectorAll('[data-comment-form]').forEach(form=>{const input=form.querySelector('textarea'),count=form.querySelector('[data-comment-count]'),button=form.querySelector('button');const update=()=>{count.textContent=input.value.length;button.disabled=input.value.trim().length<2};input.addEventListener('input',update);update()});
document.querySelectorAll('[data-comment-form],[data-feedback-form]').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button[type="submit"],button:not([type])');const original=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='<span class="spinner-border spinner-border-sm"></span> Saving...'}try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}});const payload=await response.json();if(!response.ok)throw new Error(Object.values(payload.errors||{}).flat()[0]||payload.message||'Unable to save.');showDashboardToast(payload.message||'Saved successfully.');if(form.matches('[data-comment-form]')){form.reset();form.querySelector('[data-comment-count]').textContent='0'}}catch(error){showDashboardToast(error.message||'Unable to save.','warning')}finally{if(button){button.disabled=false;button.innerHTML=original}}}));
document.querySelector('[data-raise-hand]')?.addEventListener('click',async event=>{const button=event.currentTarget;button.disabled=true;try{const response=await fetch(button.dataset.url,{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}});const data=await response.json();if(!response.ok)throw new Error(data.message||'Unable to update hand status.');button.classList.toggle('active',data.raised_hand);button.querySelector('span').textContent=data.raised_hand?'Lower hand':'Raise hand';window.syncRoomParticipants?.(data);const toastMsg=data.message||(data.raised_hand?'Your hand is raised.':'Your hand is lowered.');showDashboardToast(toastMsg,'success')}catch(error){showDashboardToast(error.message||'Unable to update hand status.','warning')}finally{button.disabled=false}});
</script>
@endsection
